    ///
    /// Declared `retryable: false`.
    pub const NOT_ATTESTED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/attestation/config-report:notAttested",
        retryable: false,
    };
    /// `vta/attestation/config-report:noConfigSnapshot`
    ///
